# 1. Données
nombres = [3, 1, 4, 1, 5, 9]

# 2. Algorithme (tri à bulles)
def tri_bulle(lst):
    n = len(lst)
    for i in range(n - 1):
        for j in range(n - i - 1):
            if lst[j] > lst[j + 1]:
                lst[j], lst[j + 1] = lst[j + 1], lst[j]

